/bin/bash -lc "cat > download_refs.py <<'PY'
import concurrent.futures as cf,urllib.request,time,pathlib,os
base='https://ftp.ensembl.org/pub/release-115/fasta/'
refs={'human':'homo_sapiens/cdna/Homo_sapiens.GRCh38.cdna.all.fa.gz','mouse':'mus_musculus/cdna/Mus_musculus.GRCm39.cdna.all.fa.gz','pig':'sus_scrofa/cdna/Sus_scrofa.Sscrofa11.1.cdna.all.fa.gz'}
tasks=[]
for sp,path in refs.items():
 url=base+path
 with urllib.request.urlopen(urllib.request.Request(url,method='HEAD')) as r:size=int(r.headers['Content-Length'])
 print(sp,size,flush=True)
 out=f'refs/{sp}.range.fa.gz'
 with open(out,'wb') as f:f.truncate(size)
 for start in range(0,size,1048576):tasks.append((url,out,start,min(start+1048576,size)-1))
def run(t):
 url,out,start,end=t
 for attempt in range(6):
  try:
   req=urllib.request.Request(url,headers={'Range':f'bytes={start}-{end}'})
   with urllib.request.urlopen(req,timeout=120) as r:
    if r.status"'!=206:raise RuntimeError(f'"'Range response {r.status}')
    data=r.read()
   if len(data)"'!=end-start+1:raise RuntimeError('"'Incorrect length')
   with open(out,'r+b') as f:f.seek(start);f.write(data)
   return len(data)
  except Exception as e:
   print('retry',out,start,e,flush=True);time.sleep(2)
 raise RuntimeError(t)
t0=time.time();n=0
with cf.ThreadPoolExecutor(max_workers=16) as pool:
 for i,result in enumerate(pool.map(run,tasks),1):
  n+=result
  if i%10==0:print(i,'/',len(tasks),'MB',round(n/1e6,1),'seconds',round(time.time()-t0),flush=True)
print('DONE',flush=True)
PY
python3 download_refs.py > refs/download.log 2>&1"

